"""Separate metadata: these tables are never created by application startup."""
from sqlalchemy import MetaData,Table,Column,String,Integer,Boolean,JSON,DateTime,ForeignKey,UniqueConstraint
from .models import Company,UserAccount,Document
metadata=MetaData()
services=Table('vault_services',metadata,Column('id',String(50),primary_key=True),Column('label',String(100),nullable=False))
grants=Table('vault_grants',metadata,Column('user_id',ForeignKey(UserAccount.id),primary_key=True),Column('company_id',ForeignKey(Company.id),primary_key=True),Column('permission',String(30),primary_key=True))
credentials=Table('vault_credentials',metadata,Column('id',String(36),primary_key=True),Column('company_id',ForeignKey(Company.id),nullable=False),Column('service_id',ForeignKey(services.c.id),nullable=False),Column('label',String(100),nullable=False),Column('envelope',JSON,nullable=False),Column('revision',Integer,nullable=False),Column('archived',Boolean,nullable=False),Column('created_at',DateTime(timezone=True),nullable=False),Column('updated_at',DateTime(timezone=True),nullable=False))
versions=Table('vault_versions',metadata,Column('credential_id',ForeignKey(credentials.c.id),primary_key=True),Column('revision',Integer,primary_key=True),Column('envelope',JSON,nullable=False),Column('actor_id',String(100),nullable=False),Column('created_at',DateTime(timezone=True),nullable=False))
certificates=Table('vault_certificates',metadata,Column('id',String(36),primary_key=True),Column('company_id',ForeignKey(Company.id),nullable=False),Column('document_id',ForeignKey(Document.id)),Column('kind',String(10),nullable=False),Column('rfc',String(13),nullable=False),Column('serial',String(100)),Column('subject',String(1000)),Column('fingerprint',String(64)),Column('valid_from',DateTime(timezone=True)),Column('valid_until',DateTime(timezone=True)),Column('origin',String(30),nullable=False),Column('reviewed_at',DateTime(timezone=True),nullable=False),Column('notes',String(2000),nullable=False),Column('revision',Integer,nullable=False),UniqueConstraint('company_id','fingerprint','kind'))
audit=Table('vault_audit',metadata,Column('id',String(36),primary_key=True),Column('company_id',ForeignKey(Company.id)),Column('actor_id',String(100),nullable=False),Column('action',String(40),nullable=False),Column('record_id',String(100)),Column('created_at',DateTime(timezone=True),nullable=False),Column('metadata',JSON,nullable=False))
settings=Table('vault_alert_settings',metadata,Column('id',Integer,primary_key=True),Column('thresholds',JSON,nullable=False))
alerts=Table('vault_alerts',metadata,Column('id',String(64),primary_key=True),Column('company_id',ForeignKey(Company.id),nullable=False),Column('source',String(30),nullable=False),Column('reference',String(100),nullable=False),Column('kind',String(40),nullable=False),Column('priority',String(10),nullable=False),Column('generated_at',DateTime(timezone=True),nullable=False),Column('due_at',DateTime(timezone=True)),Column('state',String(12),nullable=False),UniqueConstraint('source','reference','kind'))
